// Writes one overview page per lesson folder: two cards, Lý thuyết (lesson) and Thực hành (practice).
// Generated files are gitignored. Edit the lesson and practice files instead.
import { existsSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { listLessons, ROOT } from './lessons.mjs';

const esc = (s = '') => s.replace(/[&<>{}]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '{': '&#123;', '}': '&#125;' })[c]);
const GENERATED = '-overview.mdx';

const lessons = listLessons();

// drop overview files whose lesson no longer exists
const wanted = new Set(lessons.map((l) => join(l.materials, `${l.slug}${GENERATED}`)));
for (const dir of readdirSync(join(ROOT, 'lessons'), { withFileTypes: true })) {
	if (!dir.isDirectory() || !/^\d+-/.test(dir.name)) continue;
	const mats = join(ROOT, 'lessons', dir.name, 'materials');
	if (!existsSync(mats)) continue;
	for (const f of readdirSync(mats).filter((f) => f.endsWith(GENERATED))) {
		if (!wanted.has(join(mats, f))) rmSync(join(mats, f));
	}
}

for (const l of lessons) {
	const title = `Lesson ${l.num}: ${l.lesson.title}`;
	// card text is Vietnamese: the summary field. subtitle is a fallback, and flagged because it is often English
	const desc = l.lesson.summary || l.lesson.subtitle || l.lesson.title;
	if (!l.lesson.summary) console.warn(`lesson ${l.num}: no summary field, card text falls back to the English subtitle`);
	const cards = [
		`  <a class="lesson-card" href="../lesson">
    <strong class="lesson-card__title">Lý thuyết</strong>
    <span class="lesson-card__text">${esc(desc)}</span>
  </a>`,
	];
	if (l.lesson.slides) {
		cards.push(`  <a class="lesson-card" href="${esc(l.lesson.slides)}" target="_blank" rel="noopener">
    <strong class="lesson-card__title">Slides</strong>
    <span class="lesson-card__text">Slide deck của buổi này ↗</span>
  </a>`);
	}
	if (l.practice) {
		cards.push(`  <a class="lesson-card" href="../practice">
    <strong class="lesson-card__title">Thực hành</strong>
    <span class="lesson-card__text">${esc(l.practice.summary || l.practice.title)}</span>
  </a>`);
	}
	const body = `---
title: "${esc(title).replace(/"/g, '\\"')}"
description: "${esc(desc).replace(/"/g, '\\"')}"
tableOfContents: false
---

{/* Generated by site/scripts/lesson-overviews.mjs. Edit the lesson files, not this page. */}

<div class="lesson-cards">
${cards.join('\n')}
</div>
`;
	writeFileSync(join(l.materials, `${l.slug}${GENERATED}`), body);
}

console.log(`lesson overviews: ${lessons.length} lessons`);
